@api.post("/api/v1/director/pipelines/{pid}/clips/{clip_index}/rerun-image")
async def rerun_pipeline_clip_image(pid: str, clip_index: int, request: Request):
    """Re-generate the start image for a specific clip in a saved pipeline."""
    _init_pipeline()
    from services.director_pipeline import (
        GenerationCancelledError,
        PipelineBusyError,
        rerun_clip_image,
    )
    body = await request.json()
    base = wgp.server_config.get("save_path", "outputs")
    try:
        # Image generation can take minutes. Running it directly inside this
        # async route blocks every heartbeat/poll request and can make the
        # Pinokio webview reload, aborting the browser-owned bulk repair loop
        # after its first clip.
        result = await asyncio.to_thread(
            rerun_clip_image,
            base,
            pid,
            clip_index,
            prompt_override=body.get("prompt"),
        )
        return result
    except PipelineBusyError as e:
        return JSONResponse({"error": str(e)}, status_code=409)
    except GenerationCancelledError as e:
        return JSONResponse({
            "error": str(e),
            "cancelled": True,
            "output_files": list(e.output_files),
        }, status_code=409)
    except ValueError as e:
        return JSONResponse({"error": str(e)}, status_code=400)
    except Exception as e:
        traceback.print_exc()
        return JSONResponse({"error": str(e)}, status_code=500)


@api.post("/api/v1/director/pipelines/{pid}/clips/{clip_index}/rerun-video")
async def rerun_pipeline_clip_video(pid: str, clip_index: int, request: Request):
    """Re-generate the video for a specific clip in a saved pipeline."""
    _init_pipeline()
    from services.director_pipeline import (
        GenerationCancelledError,
        PipelineBusyError,
        rerun_clip_video,
    )
    body = await request.json()
    base = _workspace_dir(body["workspace"]) if body.get("workspace") else wgp.server_config.get("save_path", "outputs")
    from services.production_shot_regeneration import guard_shared_regeneration
    guard_shared_regeneration(base, body.get("workspace") or "default", body,
                              f"/api/v1/director/pipelines/{pid}/clips/{clip_index}/rerun-video")
    try:
        result = await asyncio.to_thread(
            rerun_clip_video,
            base,
            pid,
            clip_index,
            prompt_override=body.get("prompt"),
        )
        return result
    except PipelineBusyError as e:
        return JSONResponse({"error": str(e)}, status_code=409)
    except GenerationCancelledError as e:
        return JSONResponse({
            "error": str(e),
            "cancelled": True,
            "output_files": list(e.output_files),
        }, status_code=409)
    except ValueError as e:
        return JSONResponse({"error": str(e)}, status_code=400)
    except Exception as e:
        traceback.print_exc()
        return JSONResponse({"error": str(e)}, status_code=500)


@api.post("/api/v1/director/pipelines/{pid}/clips/{clip_index}/segments/{segment_index}/rerun")
async def rerun_pipeline_h3_segment(
    pid: str,
    clip_index: int,
    segment_index: int,
    request: Request,
):
    """Regenerate one editable H3 segment and its dependent continuations."""
    _init_pipeline()
    from services.director_pipeline import rerun_h3_segment
    body = await request.json()
    base = wgp.server_config.get("save_path", "outputs")
    try:
        return rerun_h3_segment(
            base,
            pid,
            clip_index,
            segment_index,
            prompt_override=body.get("prompt"),
            cascade=body.get("cascade", True) is not False,
        )
    except ValueError as e:
        return JSONResponse({"error": str(e)}, status_code=400)
    except Exception as e:
        traceback.print_exc()
        return JSONResponse({"error": str(e)}, status_code=500)


@api.post("/api/v1/director/pipelines/{pid}/rejoin")
async def rejoin_pipeline_clips(pid: str):
    """Re-join all clips from a saved pipeline using current best versions."""
    _init_pipeline()
    from services.director_pipeline import PipelineBusyError, rejoin_clips
    base = wgp.server_config.get("save_path", "outputs")
    try:
        result = await asyncio.to_thread(rejoin_clips, base, pid)
        return result
    except PipelineBusyError as e:
        return JSONResponse({"error": str(e)}, status_code=409)
    except ValueError as e:
        return JSONResponse({"error": str(e)}, status_code=400)
    except Exception as e:
        return JSONResponse({"error": str(e)}, status_code=500)


@api.delete("/api/v1/director/pipelines/{pid}")
def delete_pipeline_endpoint(pid: str):
    """Delete a saved pipeline and all media it produced (any workspace)."""
    _init_pipeline()
    from services.director_pipeline import delete_pipeline
    base = wgp.server_config.get("save_path", "outputs")
    result = delete_pipeline(base, pid)
    if not result.get("ok"):
        if result.get("error") == "running":
            raise HTTPException(status_code=409, detail="This pipeline is still running. Stop it first, then delete.")
        if result.get("error") == "state_file_locked":
            raise HTTPException(
                status_code=409,
                detail="Pipeline media was cleaned, but its state file is locked. Close any process using it and retry deletion.",
            )
        if result.get("error") == "media_locked":
            raise HTTPException(
                status_code=409,
                detail="Some pipeline media is still in use. Close its preview or any process using it, then retry deletion.",
            )
        raise HTTPException(status_code=404, detail=f"Pipeline not found: {pid}")
    print(f"[Pipeline] Deleted {pid}: {result['media_deleted']} media files removed "
          f"({result['media_deferred']} deferred) from {result['dir']}")
    return result


# ── Director V2 Planning ─────────────────────────────────────────────────

_DIRECTOR_V2_PLANNER_KEYS = (
    "clips", "scene_description", "story_description", "lyrics", "bpm",
    "reference_image_path", "character_ref_paths", "character_ref_labels",
    "location_ref_paths", "location_ref_labels", "speaker_mappings", "characters",
    "audio_path", "target_duration", "target_scenes", "narrative_mode",
    "fps", "frames_steps", "frames_minimum", "concept", "visual_style",
    "preserve_visual_style", "character_visual_style", "allow_clip_text",
    "platform", "style", "transcript", "prompt_type", "image_model",
    "video_model", "seamless", "multishot_lora_mode",
    "music_video_treatment",
)


def _director_v2_planner_kwargs(body: dict) -> dict:
    """Keep every supported Director input, including Story Lab visual refs."""
    return {key: body[key] for key in _DIRECTOR_V2_PLANNER_KEYS if key in body}

async def _director_v2_plan_body(body: dict):
    """Plan using the new Director v2 architecture (planners + renderers + validators).

    Returns structured ProductionPlan + rendered clip_plans.
    """
    if not isinstance(body, dict):
        raise HTTPException(status_code=422, detail="Director plan request must be an object")
    skill_type = body.get("skill_type", body.get("pipeline_type", "music_video"))
    tracking_id = str(body.get("activity_id") or "").strip()[:160]
    from services import llm_service
    if tracking_id:
        estimated_shots = len(body.get("clips") or []) or int(body.get("target_scenes") or 0)
        llm_service.begin_activity_tracking(
            tracking_id,
            phase="writing_scenes",
            current=0,
            total=estimated_shots,
            detail="Writing the visual scenario and scene structure…",
        )

    # Map legacy pipeline_type to skill_type
    skill_map = {
        "music_video": "music_video",
        "short_film_audio": "short_film",
        "short_film_story": "short_film",
        "podcast": "podcast",
        "viral_video": "viral_video",
    }
    skill_type = skill_map.get(skill_type, skill_type)

    plan_job_store = None
    plan_job = None
    plan_job_id = ""
    workspace = str(body.get("workspace") or _get_active_workspace())
    if skill_type == "music_video":
        from services.director_plan_jobs import (
            DirectorPlanJobStore,
            claim_director_plan_job,
        )

        plan_job_store = DirectorPlanJobStore(_workspace_dir(workspace))
        requested_job_id = str(body.get("plan_job_id") or "").strip()
        if requested_job_id:
            plan_job = plan_job_store.load(requested_job_id)
            if plan_job is None:
                raise HTTPException(status_code=404, detail="Director plan job not found")
            if str(plan_job.get("workspace") or "default") != workspace:
                raise HTTPException(status_code=409, detail="Director plan job belongs to another workspace")
            if str(plan_job.get("skillType") or "") != skill_type:
                raise HTTPException(status_code=409, detail="Director plan job uses another skill")
            if plan_job.get("status") == "completed" and isinstance(plan_job.get("result"), dict):
                return copy.deepcopy(plan_job["result"])
            saved_request = copy.deepcopy(plan_job.get("request") or {})
            if not isinstance(saved_request, dict):
                raise HTTPException(status_code=409, detail="Director plan job request is unavailable")
            if tracking_id:
                saved_request["activity_id"] = tracking_id
            saved_request["workspace"] = workspace
            saved_request["plan_job_id"] = requested_job_id
            body = saved_request
            plan_job_id = requested_job_id
            if not claim_director_plan_job(plan_job_id):
                raise HTTPException(status_code=409, detail="Director plan job is already running")
            try:
                plan_job = plan_job_store.update(
                    plan_job_id,
                    status="running",
                    phase="resuming",
                    message="Resuming missing music-video clip plans",
                    error=None,
                    finishedAt=None,
                )
            except Exception:
                from services.director_plan_jobs import release_director_plan_job
                release_director_plan_job(plan_job_id)
                raise
        else:
            durable_request = copy.deepcopy(body)
            durable_request.pop("plan_job_id", None)
            durable_request["workspace"] = workspace
            plan_job = plan_job_store.create(
                durable_request,
                workspace=workspace,
                skill_type=skill_type,
                total=len(body.get("clips") or []),
            )
            plan_job_id = str(plan_job["jobId"])
            if not claim_director_plan_job(plan_job_id):
                raise HTTPException(status_code=409, detail="Director plan job is already running")
            try:
                plan_job = plan_job_store.update(
                    plan_job_id,
                    status="running",
                    phase="starting",
                    message="Starting durable music-video planning",
                )
            except Exception:
                from services.director_plan_jobs import release_director_plan_job
                release_director_plan_job(plan_job_id)
                raise

    try:
        _ensure_llm_loaded()

        from services.director.orchestrator import DirectorOrchestrator, DirectorFlags

        flags = DirectorFlags.from_dict(body.get("director_flags", {}))
        # Raw prompts: the planner's prompts get no style lock, source-style
        # anchor, compression, no-text lock or polish.
        raw_prompts = wgp.server_config.get("services", {}).get("raw_prompts") is True
        flags.raw_prompts = raw_prompts
        director = DirectorOrchestrator(
            llm_generate=llm_service.generate,
            llm_generate_streaming=llm_service.generate_streaming,
            flags=flags,
        )

        # Build planner kwargs from request body
        from services.director.planners.music_video import normalize_music_video_treatment
        normalized_treatment = normalize_music_video_treatment(
            body.get("music_video_treatment")
        )
        direct_video = normalized_treatment.get("generation_mode") == "direct_video"
        if skill_type == "music_video" or direct_video:
            body["music_video_treatment"] = normalized_treatment
        planner_kwargs = _director_v2_planner_kwargs(body)

        # NSFW from server config (enforced: never with public providers)
        services = wgp.server_config.get("services", {})
        provider = _effective_llm_routing(services)[0]
        planner_kwargs["nsfw"] = services.get("nsfw_mode", False) and provider not in _PUBLIC_LLM_PROVIDERS

        if plan_job_store is not None and plan_job is not None:
            planner_kwargs["completed_shot_plans"] = copy.deepcopy(
                plan_job.get("completedShotPlans") or []
            )

            def _checkpoint_music_plan_batch(event: dict) -> None:
                usage = (
                    llm_service.get_activity_tracking(tracking_id).get("usage")
                    if tracking_id else {}
                ) or {}
                event_type = str(event.get("event") or "")
                indices = [
                    int(value) for value in event.get("indices") or []
                    if isinstance(value, int) or str(value).isdigit()
                ]
                if event_type == "call_started":
                    plan_job_store.begin_call(
                        plan_job_id,
                        indices=indices,
                        phase=str(event.get("phase") or "planning"),
                        usage=usage,
                    )
                    llm_service.update_activity_tracking(
                        tracking_id,
                        phase=f"planning_{event.get('phase') or 'batch'}",
                        current=len((plan_job_store.load(plan_job_id) or {}).get("completedIndices") or []),
                        total=len(body.get("clips") or []),
                        detail=f"Planning clip indexes {', '.join(map(str, indices))}…",
                    )
                elif event_type == "batch_completed":
                    shot_plans = event.get("shot_plans") or []
                    plan_job_store.record_batch(
                        plan_job_id,
                        indices=indices,
                        shot_plans=shot_plans,
                        usage=usage,
                    )
                    llm_service.update_activity_tracking(
                        tracking_id,
                        phase="batch_completed",
                        current=len((plan_job_store.load(plan_job_id) or {}).get("completedIndices") or []),
                        total=len(body.get("clips") or []),
                        detail=f"Saved clip indexes {', '.join(map(str, indices))}.",
                    )

            planner_kwargs["batch_checkpoint"] = _checkpoint_music_plan_batch

        # Prompt polish mode: off | full_guide | light_guide | third_pass.
        # Off by default: the planner's prompts reach the models as written.
        # The third pass is model-aware; native H3 prompts retain their
        # deterministic compiler while applicable prompts are polished.
        polish_mode = "off" if raw_prompts else services.get("director_prompt_polish", "off")
        video_model = body.get("video_model", "")
        image_model = body.get("image_model", "")

        # Extract activated LoRA filenames for guide loading
        video_loras_activated = (body.get("video_loras") or {}).get("activated_loras", [])
        image_loras_activated = (body.get("image_loras") or {}).get("activated_loras", [])

        # For guide injection modes (full/light), pass polish block to planners via kwargs
        if polish_mode in ("full_guide", "light_guide"):
            from services.director.prompt_polish import build_polish_block
            guide_mode = "full" if polish_mode == "full_guide" else "light"
            polish_block = build_polish_block(video_model, image_model, guide_mode,
                                              video_loras=video_loras_activated, image_loras=image_loras_activated)
            if polish_block:
                planner_kwargs["polish_block"] = polish_block

        # Plan
        plan = await asyncio.get_event_loop().run_in_executor(
            None,
            lambda: llm_service.run_with_activity_tracking(
                tracking_id,
                lambda: director.plan(skill_type, **planner_kwargs),
            ),
        )

        # Render
        planned_shots = len(getattr(plan, "shots", []) or [])
        llm_service.update_activity_tracking(
            tracking_id,
            phase="writing_prompts",
            current=0,
            total=planned_shots,
            detail=f"Turning {planned_shots} scenes into image and video prompts…",
        )
        has_reference = not direct_video and bool(
            body.get("reference_image_path")
            or body.get("character_ref_paths")
            or body.get("location_ref_paths")
        )
        prompt_type = "video" if direct_video else body.get("prompt_type", "both")
        rendered = director.render_plan(plan, prompt_type=prompt_type, has_reference=has_reference)
        clip_plans = director.plan_to_clip_plans(rendered)

        # Third-pass polish: run each prompt through the enhance pipeline
        if polish_mode == "third_pass" and clip_plans and not direct_video:
            from services.director.prompt_polish import polish_prompts_third_pass
            nsfw = planner_kwargs.get("nsfw", False)
            # Forward character profiles so polish can map names → correct
            # non-human descriptors (e.g. Lumi → the white unicorn) instead
            # of falling back to generic "the woman" / "the man".
            polish_chars = planner_kwargs.get("characters", []) or []
            llm_service.update_activity_tracking(
                tracking_id,
                phase="polishing_prompts",
                current=0,
                total=len(clip_plans),
                detail=f"Polishing shot 1 of {len(clip_plans)}…",
            )

            def _report_polish_progress(current, total):
                shot = clip_plans[max(0, min(current - 1, len(clip_plans) - 1))]
                detail = str(shot.get("image_prompt") or shot.get("video_prompt") or "").strip()
                llm_service.update_activity_tracking(
                    tracking_id,
                    phase="polishing_prompts",
                    current=current,
                    total=total,
                    detail=detail[:1200],
                )

            clip_plans = await asyncio.get_event_loop().run_in_executor(
                None,
                lambda: llm_service.run_with_activity_tracking(
                    tracking_id,
                    lambda: polish_prompts_third_pass(
                        clip_plans, video_model, image_model, nsfw,
                        video_loras=video_loras_activated, image_loras=image_loras_activated,
                        characters=polish_chars,
                        progress_callback=_report_polish_progress,
                    ),
                ),
            )

        from services.director.policies import (
            enforce_visual_style_on_clip_plans,
            no_visible_text_lock_applies,
        )
        # The no-visible-text lock is for sung projects (music videos) only.
        clip_text_allowed = not no_visible_text_lock_applies({
            "pipeline_type": skill_type,
            "allow_clip_text": body.get("allow_clip_text"),
        })
        clip_plans = clip_plans if raw_prompts else enforce_visual_style_on_clip_plans(
            clip_plans,
            "" if direct_video else body.get("visual_style", ""),
            preserve=(
                False if direct_video
                else bool(body.get("preserve_visual_style", False))
            ),
            has_reference=has_reference,
            character_visual_style=(
                "" if direct_video else body.get("character_visual_style", "")
            ),
            allow_clip_text=True if direct_video else clip_text_allowed,
        )
        if direct_video:
            from services.director.policies import enforce_direct_video_on_clip_plans
            clip_plans = enforce_direct_video_on_clip_plans(
                clip_plans,
                normalized_treatment.get("direct_video_master_prompt"),
                audio_direction=body.get("h3_audio_prompt", ""),
                allow_clip_text=raw_prompts or clip_text_allowed,
            )
        elif _is_minimax_h3_model(video_model):
            from services.director.minimax_h3_prompting import (
                adapt_clip_plans_for_h3,
                h3_audio_policy_from_payload,
            )
            serialized_plan = plan.to_dict()
            clip_plans = adapt_clip_plans_for_h3(
                clip_plans,
                serialized_plan.get("shots") or [],
                reference_mode=body.get("h3_reference_mode", "first_frame"),
                audio_direction=body.get("h3_audio_prompt", ""),
                h3_audio_policy=h3_audio_policy_from_payload(body),
            )
            clip_plans = clip_plans if raw_prompts else enforce_visual_style_on_clip_plans(
                clip_plans,
                body.get("visual_style", ""),
                preserve=bool(body.get("preserve_visual_style", False)),
                has_reference=has_reference,
                character_visual_style=body.get("character_visual_style", ""),
                allow_clip_text=clip_text_allowed,
            )
        llm_service.update_activity_tracking(
            tracking_id,
            status="completed",
            phase="completed",
            current=len(clip_plans),
            total=len(clip_plans),
            detail=f"{len(clip_plans)} visual shot plans ready for review.",
        )
        result = {
            "clip_plans": clip_plans,
            "production_plan": plan.to_dict(),
            "skill_type": skill_type,
        }
        if plan_job_store is not None and plan_job_id:
            result["plan_job_id"] = plan_job_id
            plan_job_store.update(
                plan_job_id,
                status="completed",
                phase="completed",
                message=f"{len(clip_plans)} visual shot plans ready for review",
                activeBatch=[],
                result=copy.deepcopy(result),
                error=None,
                finishedAt=time.time(),
            )
        return result

    except Exception as e:
        import traceback
        traceback.print_exc()
        recoverable_failure = None
        if plan_job_store is not None and plan_job_id:
            try:
                failed_job = plan_job_store.update(
                    plan_job_id,
                    status="failed",
                    phase="failed",
                    message="Music-video planning stopped; completed batches are recoverable",
                    activeBatch=[],
                    error=str(e),
                    finishedAt=time.time(),
                )
                from services.director_plan_jobs import build_director_plan_failure_detail
                recoverable_failure = build_director_plan_failure_detail(failed_job, str(e))
            except Exception as checkpoint_error:
                print(f"[DirectorPlanJob] Could not persist failure state: {checkpoint_error}")
        llm_service.update_activity_tracking(
            tracking_id, status="failed", detail=str(e), error=str(e)
        )
        if recoverable_failure is not None:
            raise HTTPException(status_code=500, detail=recoverable_failure)
        raise HTTPException(status_code=500, detail=str(e))
    finally:
        if plan_job_id:
            from services.director_plan_jobs import release_director_plan_job
            release_director_plan_job(plan_job_id)


@api.post("/api/v1/director/v2/plan")
async def director_v2_plan(request: Request):
    """Run a Director plan while checkpointing bounded music-video batches."""
    return await _director_v2_plan_body(await request.json())


def _director_plan_job_store(workspace: str):
    from services.director_plan_jobs import DirectorPlanJobStore
    return DirectorPlanJobStore(_workspace_dir(workspace))


@api.get("/api/v1/director/v2/plan/jobs")
def list_director_v2_plan_jobs(workspace: str = "default"):
    """List durable Director planning checkpoints without exposing prompts."""
    store = _director_plan_job_store(workspace)
    return {
        "jobs": [store.public_snapshot(job) for job in store.list()],
    }


@api.get("/api/v1/director/v2/plan/jobs/{job_id}")
def get_director_v2_plan_job(job_id: str, workspace: str = "default"):
    store = _director_plan_job_store(workspace)
    job = store.load(job_id)
    if job is None:
        raise HTTPException(status_code=404, detail="Director plan job not found")
    return store.public_snapshot(job)


@api.post("/api/v1/director/v2/plan/jobs/{job_id}/resume")
async def resume_director_v2_plan_job(
    job_id: str,
    request: Request,
    workspace: str = "default",
):
    """Resume only the missing indexes from a durable planning checkpoint."""
    store = _director_plan_job_store(workspace)
    job = store.load(job_id)
    if job is None:
        raise HTTPException(status_code=404, detail="Director plan job not found")
    if job.get("status") == "completed" and isinstance(job.get("result"), dict):
        return copy.deepcopy(job["result"])
    body = copy.deepcopy(job.get("request") or {})
    if not isinstance(body, dict):
        raise HTTPException(status_code=409, detail="Director plan job request is unavailable")
    try:
        override = await request.json()
    except Exception:
        override = {}
    if isinstance(override, dict) and str(override.get("activity_id") or "").strip():
        body["activity_id"] = str(override["activity_id"]).strip()[:160]
    body["workspace"] = workspace
    body["plan_job_id"] = job_id
    return await _director_v2_plan_body(body)


@api.get("/api/v1/director/v2/plan/progress/{activity_id}")
def director_v2_plan_progress(activity_id: str):
    """Return live sub-step and provider-reported token usage for one plan."""
    from services import llm_service
    state = llm_service.get_activity_tracking(activity_id)
    if not state:
        raise HTTPException(status_code=404, detail="Planning activity not found")
    return state


def _run_generation_with_preparation(job_id: str) -> bool:
    """Finish deferred, non-GPU preparation before entering generation FIFO.

    H3 window planning may load an LLM or call a remote provider.  It must not
    block ``POST /generate`` and it must not reserve the scarce video lane
    while doing so.  The pending request is persisted inside the job params so
    crash recovery can replay this same worker before starting inference.
    """
    job = _jobs.get(job_id)
    if not isinstance(job, dict):
        return False
    try:
        native_worker = _image_generation_commands.native_worker(job)
    except HTTPException as error:
        finish_job(job, "failed", error=str(error.detail), message="Command recovery could not be verified")
        return False
    if native_worker is not None:
        return bool(native_worker(job_id))
    params = job.get("params") if isinstance(job.get("params"), dict) else {}
    pending = params.get("_h3_window_plan_pending")
    if not isinstance(pending, dict):
        return bool(_run_generation(job_id))
    if is_cancel_requested(job):
        _remove_persisted_generation_job(job)
        return False
    if not try_start(
        job,
        phase="planning",
        message="Planning H3 window-by-window prompts with the writing model…",
        acquired_resources=[],
    ):
        if is_cancel_requested(job):
            _remove_persisted_generation_job(job)
        return False

    _persist_generation_job(job)
    planner_llm = None
    try:
        from services import llm_service as planner_llm
        from services.h3_window_planner import plan_h3_sliding_windows

        def _plan_windows():
            try:
                _ensure_llm_loaded()
            except Exception as load_error:
                # The planner has a deterministic fallback, so a missing
                # optional LLM must not make an otherwise valid H3 job fail.
                print(
                    "[MiniMax H3] Planner LLM unavailable; using fallback: "
                    f"{load_error}"
                )
            services = wgp.server_config.get("services", {})
            provider = _effective_llm_routing(services)[0]
            nsfw = (
                services.get("nsfw_mode", False)
                and provider not in _PUBLIC_LLM_PROVIDERS
            )
            expected_count = int(pending.get("expected_count") or 0)
            if expected_count <= 0:
                raise RuntimeError("H3 window plan has no target windows")
            print(
                f"[MiniMax H3] Planning {expected_count} window-local prompts "
                "after VRAM-safe geometry "
                f"({int(pending.get('window_frames') or 0)} frames/window)."
            )
            result = plan_h3_sliding_windows(
                str(params.get("prompt") or ""),
                model_type=str(pending.get("model_type") or ""),
                resolution=str(pending.get("resolution") or ""),
                total_frames=int(pending.get("total_frames") or 0),
                window_frames=int(pending.get("window_frames") or 0),
                overlap_frames=int(pending.get("overlap_frames") or 0),
                discard_frames=int(pending.get("discard_frames") or 0),
                fps=float(pending.get("fps") or 24),
                has_start_image=bool(pending.get("has_start_image")),
                has_end_image=bool(pending.get("has_end_image")),
                image_paths=list(pending.get("image_paths") or []) or None,
                nsfw=bool(nsfw),
                planning_style=str(pending.get("planning_style") or "faithful"),
                h3_audio_policy=str(pending.get("h3_audio_policy") or "native"),
                reference_context=str(pending.get("reference_context") or ""),
            )
            prompts = result.get("window_prompts") if isinstance(result, dict) else None
            if (
                not isinstance(prompts, list)
                or len(prompts) != expected_count
                or not all(isinstance(item, str) and item.strip() for item in prompts)
            ):
                raise RuntimeError(
                    "H3 window planner returned an incomplete prompt plan "
                    f"({len(prompts) if isinstance(prompts, list) else 0}/"
                    f"{expected_count})"
                )
            return result, list(prompts)

        # Correlate any child LLM call with the visible generation root.  The
        # fallback keeps model-free tests and older embedded callers working.
        try:
            from services.task_manager import task_context_scope
        except Exception:
            planned, window_prompts = _plan_windows()
        else:
            with task_context_scope(
                task_id=job.get("task_id"),
                root_id=job.get("root_task_id") or job.get("task_id"),
                workspace=job.get("workspace") or "default",
                workspace_dir=job.get("out_dir")
                or _workspace_dir(job.get("workspace") or "default"),
            ):
                planned, window_prompts = _plan_windows()

        if is_cancel_requested(job):
            _remove_persisted_generation_job(job)
            return False
        prepared_params = copy.deepcopy(params)
        prepared_params.pop("_h3_window_plan_pending", None)
        prepared_params["minimax_h3_window_storyboard"] = True
        prepared_params["h3_window_prompts"] = window_prompts
        prepared_params["h3_window_plan_signature"] = str(
            pending.get("signature") or ""
        )
        prepared_params["h3_window_plan"] = planned
        if not update_job(
            job,
            params=prepared_params,
            phase="planning",
            message=(
                f"H3 prompt plan ready ({len(window_prompts)} windows); "
                "queuing video generation…"
            ),
        ):
            _remove_persisted_generation_job(job)
            return False
        _persist_generation_job(job)
        if not try_requeue(
            job,
            phase="waiting_resource",
            message="H3 prompt plan ready · waiting for the local video GPU…",
            started_at=None,
        ):
            _remove_persisted_generation_job(job)
            return False
        _persist_generation_job(job)
        return bool(_run_generation(job_id))
    except Exception as error:
        traceback.print_exc()
        if not is_cancel_requested(job):
            finish_job(
                job,
                "failed",
                error=str(error),
                message=f"H3 window planning failed: {error}",
                phase="planning",
            )
        _remove_persisted_generation_job(job)
        return False
    finally:
        # A local writing model cannot remain beside H3's 20B/33B runtime.
        if planner_llm is not None:
            try:
                if (
                    planner_llm.is_loaded()
                    and planner_llm.get_status().get("provider") == "local"
                ):
                    planner_llm.unload_model()
            except Exception as unload_error:
                print(f"[MiniMax H3] Planner LLM unload skipped: {unload_error}")
        # Deferred planning has no abort-state registration. Confirm terminal
        # cancellation only after the planner call and its model cleanup have
        # both returned.
        acknowledge_cancel(job)


