@api.get("/api/v1/outputs/{name}/metadata")
def get_output_metadata(name: str, workspace: str | None = None):
    """Get metadata for an output file. Tries sidecar first, then embedded."""
    out_dir = _workspace_dir(workspace)
    filepath = _safe_join(out_dir, name)
    if filepath is None or not os.path.isfile(filepath):
        raise HTTPException(status_code=404, detail="Output file not found")

    # Helper: read embedded metadata from the media file
    def _read_embedded():
        ext = os.path.splitext(name)[1].lower()
        try:
            if ext in (".mp4", ".mkv"):
                from shared.utils.video_metadata import read_metadata_from_video
                return read_metadata_from_video(filepath)
            elif ext in (".png", ".jpg", ".jpeg", ".webp"):
                from shared.utils.audio_video import read_image_metadata
                return read_image_metadata(filepath)
            elif ext in (".wav", ".mp3"):
                from shared.utils.audio_metadata import read_audio_metadata
                return read_audio_metadata(filepath)
        except Exception:
            pass
        return None

    # Strategy 1: Read sidecar .meta.json
    meta_path = os.path.join(out_dir, os.path.splitext(name)[0] + ".meta.json")
    if os.path.isfile(meta_path):
        try:
            with open(meta_path, "r", encoding="utf-8") as f:
                sidecar = json.load(f)
            # Merge actual seed from embedded metadata if sidecar has seed=-1
            params = sidecar.get("params", {})
            if params.get("seed", -1) == -1:
                embedded = _read_embedded()
                if embedded and "seed" in embedded:
                    params["seed"] = embedded["seed"]
                else:
                    resolved_seed = _extract_output_seed(name)
                    if resolved_seed is not None:
                        params["seed"] = resolved_seed
            # Legacy Director finals may contain a wall-clock total (including
            # review/stopped time) and only a pipeline ID in params. Recover
            # active timings plus the exact model and resolution from the
            # checkpoint. New sidecars carry the basis and render context, so
            # they avoid the extra checkpoint read.
            pipeline_id = (
                sidecar.get("director_pipeline_id")
                or params.get("director_pipeline_id")
                or params.get("_director_pipeline_id")
            )
            needs_pipeline_context = bool(
                pipeline_id
                and (
                    sidecar.get("generation_timing_basis") != "active_stages"
                    or not params.get("model_type")
                    or not params.get("resolution")
                )
            )
            if needs_pipeline_context:
                from services.director_pipeline import (
                    enrich_output_metadata_with_pipeline_timing,
                    load_pipeline_state,
                )
                pipeline = load_pipeline_state(out_dir, str(pipeline_id))
                if pipeline:
                    sidecar = enrich_output_metadata_with_pipeline_timing(
                        sidecar,
                        pipeline,
                    )
            return {"source": "sidecar", **sidecar}
        except Exception:
            pass

    # Strategy 2: Read embedded metadata from media file
    embedded = _read_embedded()
    if embedded:
        return {"source": "embedded", "params": embedded}

    return {"source": "none", "params": None}


_alternative_song_sidecar_lock = threading.RLock()


def _alternative_song_parent(name: str, workspace: str | None = None) -> tuple[str, str, str, dict]:
    """Return workspace dir, video path, basename and sidecar for one mix."""
    from services.alternative_songs import load_sidecar

    out_dir = _workspace_dir(workspace)
    filepath = _safe_join(out_dir, name)
    if filepath is None or not os.path.isfile(filepath):
        raise HTTPException(status_code=404, detail="Videoclip not found")
    if os.path.splitext(filepath)[1].lower() not in {".mp4", ".mkv", ".webm", ".mov"}:
        raise HTTPException(status_code=400, detail="Alternative songs are for video mixes")
    return out_dir, filepath, os.path.basename(filepath), load_sidecar(filepath)


def _alternative_song_sources(out_dir: str, video_name: str, sidecar: dict) -> list[dict]:
    from services.alternative_songs import resolve_remount_sources

    sources = resolve_remount_sources(sidecar, video_name, out_dir)
    if not sources:
        raise HTTPException(
            status_code=400,
            detail="This videoclip has no reusable shots on disk to remount",
        )
    return sources


def _alternative_song_job_is_active(job_id: str) -> bool:
    """Only an in-process editor worker can finish a persisted remount."""
    snapshot = _video_editor_job_snapshot(job_id)
    return bool(
        snapshot
        and str(snapshot.get("status") or "") not in {"completed", "failed", "cancelled"}
        and snapshot.get("_worker_active")
    )


def _recover_stale_alternative_song_mounts(video_path: str, sidecar: dict) -> bool:
    from services.alternative_songs import recover_stale_mounts, save_sidecar

    changed = recover_stale_mounts(sidecar, _alternative_song_job_is_active)
    if changed:
        save_sidecar(video_path, sidecar)
    return changed


def _run_alternative_song_mount(
    job_id: str,
    *,
    out_dir: str,
    video_path: str,
    video_name: str,
    audio_path: str,
    output_path: str,
    song_id: str,
    workspace: str,
    seed: int,
) -> None:
    from services.alternative_songs import (
        find_song,
        load_sidecar,
        plan_timeline,
        remount_clips,
        resolve_remount_sources,
        save_sidecar,
        write_mounted_sidecar,
    )

    def fail(message: str) -> None:
        with _alternative_song_sidecar_lock:
            sidecar = load_sidecar(video_path)
            song = find_song(sidecar, song_id=song_id)
            if song is not None:
                song["status"] = "failed"
                song["job_id"] = job_id
                save_sidecar(video_path, sidecar)
        _video_editor_job_update(
            job_id,
            status="failed",
            phase="failed",
            error=message,
            message=message,
            output_files=[],
            acquired_resources=[],
            finished_at=time.time(),
            _resource_acquired=False,
            _worker_active=False,
        )

    try:
        _video_editor_job_update(
            job_id,
            status="waiting_resource",
            phase="waiting_resource",
            message="Waiting for the local FFmpeg lane…",
            acquired_resources=[],
        )
        with _alternative_song_sidecar_lock:
            sidecar = load_sidecar(video_path)
            sources = resolve_remount_sources(sidecar, video_name, out_dir)
            song = find_song(sidecar, song_id=song_id)
            if song is None:
                raise ValueError("The alternative song disappeared before remount")
            target = float(song.get("duration_seconds") or 0)
        planned = plan_timeline(sources, target, rng=random.Random(seed))
        try:
            with resource_scheduler.coordinator.acquire(
                _VIDEO_EDITOR_FFMPEG_LANE,
                task_id=str((_video_editor_job_snapshot(job_id) or {}).get("task_id") or job_id),
                description="Alternative song remount",
                cancelled=lambda: _video_editor_cancel_requested(job_id),
            ):
                started = _video_editor_job_update(
                    job_id,
                    status="running",
                    phase="rendering",
                    message="Remounting videoclip with the alternative song…",
                    started_at=time.time(),
                    acquired_resources=[_VIDEO_EDITOR_FFMPEG_LANE.key],
                    _resource_acquired=True,
                )
                if (
                    _video_editor_cancel_requested(job_id)
                    or str(started.get("status") or "") in _VIDEO_EDITOR_TERMINAL
                ):
                    raise resource_scheduler.ResourceAcquireCancelled(
                        f"Alternative song remount {job_id} was cancelled before FFmpeg started"
                    )
                remount_clips(
                    planned,
                    audio_path,
                    output_path,
                    abort_callback=lambda: _video_editor_cancel_requested(job_id),
                )
        except resource_scheduler.ResourceAcquireCancelled:
            current = _video_editor_job_snapshot(job_id) or {}
            deferred = bool(current.get("started_at"))
            with _alternative_song_sidecar_lock:
                sidecar = load_sidecar(video_path)
                song = find_song(sidecar, song_id=song_id)
                if song is not None and str(song.get("status") or "") == "mounting":
                    song["status"] = "attached"
                    song["job_id"] = None
                    save_sidecar(video_path, sidecar)
            _finish_video_editor_cancelled(
                job_id,
                output_path,
                message=(
                    "Cancelled after FFmpeg reached a safe boundary"
                    if deferred else "Cancelled before FFmpeg started"
                ),
                cancel_mode="deferred" if deferred else "immediate",
                safe_boundary=(
                    "after_current_ffmpeg_render" if deferred else "before_ffmpeg"
                ),
            )
            return

        if _video_editor_cancel_requested(job_id):
            with _alternative_song_sidecar_lock:
                sidecar = load_sidecar(video_path)
                song = find_song(sidecar, song_id=song_id)
                if song is not None:
                    song["status"] = "attached"
                    song["job_id"] = None
                    save_sidecar(video_path, sidecar)
            _finish_video_editor_cancelled(
                job_id,
                output_path,
                message="Cancelled after FFmpeg reached a safe boundary",
                cancel_mode="deferred",
                safe_boundary="after_current_ffmpeg_render",
            )
            return

        with _alternative_song_sidecar_lock:
            sidecar = load_sidecar(video_path)
            song = find_song(sidecar, song_id=song_id)
            if song is None:
                raise ValueError("The alternative song disappeared after remount")
            write_mounted_sidecar(
                output_path=output_path,
                parent_name=video_name,
                parent_sidecar=sidecar,
                song=song,
                planned=planned,
                job_id=job_id,
                workspace=workspace,
            )
            save_sidecar(video_path, sidecar)
        output_name = os.path.basename(output_path)
        _video_editor_job_update(
            job_id,
            status="completed",
            phase="completed",
            progress=100,
            current=100,
            message="Alternative song remount complete",
            filename=output_name,
            url=f"/api/v1/file/{output_name}",
            output_files=[output_name],
            acquired_resources=[],
            finished_at=time.time(),
            _resource_acquired=False,
            _worker_active=False,
        )
    except Exception as exc:
        traceback.print_exception(type(exc), exc, exc.__traceback__)
        _remove_video_editor_output_bundle(output_path)
        fail(str(exc))


@api.get("/api/v1/outputs/{name}/alternative-songs")
def list_alternative_songs(name: str, workspace: str | None = None):
    """List songs attached to an assembled videoclip without remounting."""
    from services.alternative_songs import describe_parent

    with _alternative_song_sidecar_lock:
        out_dir, filepath, video_name, sidecar = _alternative_song_parent(name, workspace)
        _recover_stale_alternative_song_mounts(filepath, sidecar)
        sources = _alternative_song_sources(out_dir, video_name, sidecar)
        return describe_parent(
            video_name=video_name,
            video_path=filepath,
            sidecar=sidecar,
            source_files=sources,
        )


@api.post("/api/v1/outputs/{name}/alternative-songs")
def attach_alternative_song(name: str, body: dict, workspace: str | None = None):
    """Attach an existing audio output as an alternative song. No GPU work."""
    with _alternative_song_sidecar_lock:
        return _attach_alternative_song_locked(name, body, workspace)


def _attach_alternative_song_locked(name: str, body: dict, workspace: str | None = None):
    from services.alternative_songs import attach_song, describe_parent, public_song, save_sidecar

    audio_name = str((body or {}).get("audio_name") or "").strip()
    if not audio_name:
        raise HTTPException(status_code=400, detail="audio_name is required")
    ws = workspace if workspace is not None else (body or {}).get("workspace")
    out_dir, filepath, video_name, sidecar = _alternative_song_parent(name, ws)
    sources = _alternative_song_sources(out_dir, video_name, sidecar)
    try:
        audio_path = _resolve_video_editor_audio_source(audio_name, ws)
        from services.alternative_songs import probe_song_duration
        duration = probe_song_duration(audio_path)
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    record = attach_song(sidecar, audio_name=os.path.basename(audio_path), duration_seconds=duration)
    save_sidecar(filepath, sidecar)
    parent = describe_parent(
        video_name=video_name, video_path=filepath, sidecar=sidecar, source_files=sources,
    )
    return {"song": public_song(record), **parent}


@api.delete("/api/v1/outputs/{name}/alternative-songs/{song_id}")
def delete_alternative_song(name: str, song_id: str, workspace: str | None = None):
    with _alternative_song_sidecar_lock:
        return _delete_alternative_song_locked(name, song_id, workspace)


def _delete_alternative_song_locked(name: str, song_id: str, workspace: str | None = None):
    from services.alternative_songs import public_song, remove_song, save_sidecar

    _out_dir, filepath, _video_name, sidecar = _alternative_song_parent(name, workspace)
    _recover_stale_alternative_song_mounts(filepath, sidecar)
    try:
        removed = remove_song(sidecar, song_id)
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    save_sidecar(filepath, sidecar)
    return {"removed": public_song(removed)}


@api.post("/api/v1/outputs/{name}/alternative-songs/{song_id}/mount", status_code=202)
def mount_alternative_song(name: str, song_id: str, body: dict | None = None, workspace: str | None = None):
    """Remount the videoclip with an attached alternative song using FFmpeg only."""
    with _alternative_song_sidecar_lock:
        return _mount_alternative_song_locked(name, song_id, body, workspace)


def _mount_alternative_song_locked(
    name: str,
    song_id: str,
    body: dict | None = None,
    workspace: str | None = None,
):
    from services.alternative_songs import (
        attach_song,
        find_song,
        public_song,
        save_sidecar,
        unique_mounted_name,
        probe_song_duration,
    )

    payload = body if isinstance(body, dict) else {}
    ws = workspace if workspace is not None else payload.get("workspace")
    out_dir, filepath, video_name, sidecar = _alternative_song_parent(name, ws)
    _recover_stale_alternative_song_mounts(filepath, sidecar)
    _alternative_song_sources(out_dir, video_name, sidecar)
    record = find_song(sidecar, song_id=song_id)
    if record is None:
        audio_name = str(payload.get("audio_name") or "").strip()
        if not audio_name:
            raise HTTPException(status_code=404, detail="Alternative song not found")
        try:
            audio_path = _resolve_video_editor_audio_source(audio_name, ws)
            record = attach_song(
                sidecar,
                audio_name=os.path.basename(audio_path),
                duration_seconds=probe_song_duration(audio_path),
            )
            song_id = str(record["id"])
        except ValueError as exc:
            raise HTTPException(status_code=400, detail=str(exc)) from exc
    if str(record.get("status") or "") == "mounting":
        raise HTTPException(status_code=409, detail="That song is already remounting")
    try:
        audio_path = _resolve_video_editor_audio_source(str(record.get("audio_name") or ""), ws)
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    try:
        seed = int(payload.get("seed") if payload.get("seed") is not None else 1)
    except (TypeError, ValueError) as exc:
        raise HTTPException(status_code=400, detail="seed must be an integer") from exc
    output_name = unique_mounted_name(out_dir, video_name, str(record.get("audio_name") or "song"))
    output_path = os.path.join(out_dir, output_name)
    job_id = f"alt-song-{uuid.uuid4().hex[:12]}"
    task_id, root_task_id, parent_task_id = _video_editor_task_identity(payload, job_id)
    now = time.time()
    job = {
        "job_id": job_id,
        "task_id": task_id,
        "root_task_id": root_task_id,
        "parent_task_id": parent_task_id,
        "workspace": ws or _get_active_workspace(),
        "status": "queued",
        "phase": "queued",
        "progress": 0,
        "current": 0,
        "total": 100,
        "message": "Waiting to remount the alternative song…",
        "filename": None,
        "url": None,
        "output_files": [],
        "result": None,
        "error": None,
        "provider": "local",
        "model": "FFmpeg",
        "server_origin": "local",
        "resource_lane": _VIDEO_EDITOR_FFMPEG_LANE.key,
        "resource_requirements": [_VIDEO_EDITOR_FFMPEG_LANE.key],
        "acquired_resources": [],
        "created_at": now,
        "queued_at": now,
        "updated_at": now,
        "_cancel_requested": False,
        "_resource_acquired": False,
        "_worker_active": True,
    }
    record["status"] = "mounting"
    record["job_id"] = job_id
    save_sidecar(filepath, sidecar)
    try:
        snapshot = _register_video_editor_job(job)
    except Exception as exc:
        record["status"] = "attached"
        record["job_id"] = None
        save_sidecar(filepath, sidecar)
        raise HTTPException(status_code=500, detail=f"Could not queue remount: {exc}") from exc
    worker = threading.Thread(
        target=_run_alternative_song_mount,
        kwargs={
            "job_id": job_id,
            "out_dir": out_dir,
            "video_path": filepath,
            "video_name": video_name,
            "audio_path": audio_path,
            "output_path": output_path,
            "song_id": song_id,
            "workspace": str(job["workspace"]),
            "seed": seed,
        },
        daemon=True,
        name=f"maestro-{job_id}",
    )
    try:
        worker.start()
    except Exception as exc:
        record["status"] = "attached"
        record["job_id"] = None
        save_sidecar(filepath, sidecar)
        _video_editor_job_update(
            job_id,
            status="failed",
            phase="failed",
            error=str(exc),
            message=f"Could not start remount: {exc}",
            finished_at=time.time(),
            _worker_active=False,
        )
        raise HTTPException(status_code=500, detail=f"Could not start remount: {exc}") from exc
    return {
        "job_id": job_id,
        "task_id": snapshot.get("task_id"),
        "status": snapshot.get("status"),
        "song": public_song(record),
        "output_name": output_name,
    }


def _saved_video_context_for_extra_info(name: str):
    """Load sidecar/pipeline context without reading the media itself."""
    out_dir = _workspace_dir()
    filepath = _safe_join(out_dir, name)
    if filepath is None or not os.path.isfile(filepath):
        raise HTTPException(status_code=404, detail="Output video not found")
    if os.path.splitext(filepath)[1].lower() not in {".mp4", ".mkv", ".webm", ".mov", ".gif"}:
        raise HTTPException(status_code=400, detail="Extra info is available for videos only")

    meta_path = os.path.splitext(filepath)[0] + ".meta.json"
    if not os.path.isfile(meta_path):
        raise HTTPException(
            status_code=400,
            detail="This video has no saved prompt metadata; media re-analysis is disabled",
        )
    try:
        with open(meta_path, "r", encoding="utf-8") as handle:
            metadata = json.load(handle)
    except (OSError, ValueError, json.JSONDecodeError) as error:
        raise HTTPException(status_code=500, detail="Could not read the video's saved metadata") from error
    if not isinstance(metadata, dict):
        raise HTTPException(status_code=500, detail="The video's saved metadata is invalid")

    params = metadata.get("params") if isinstance(metadata.get("params"), dict) else {}
    pipeline_id = (
        metadata.get("director_pipeline_id")
        or params.get("director_pipeline_id")
        or params.get("_director_pipeline_id")
    )
    pipeline = None
    # Pipeline IDs are generated as short hex strings. Validate before asking
    # for its checkpoint filename. Read that JSON directly: the Extra info
    # feature must not invoke media recovery/reconciliation or analyse frames.
    if pipeline_id and re.fullmatch(r"[A-Za-z0-9_-]{1,64}", str(pipeline_id)):
        pipeline_path = _safe_join(out_dir, f"_director_pipeline_{pipeline_id}.json")
        if pipeline_path and os.path.isfile(pipeline_path):
            try:
                with open(pipeline_path, "r", encoding="utf-8") as handle:
                    candidate = json.load(handle)
                if isinstance(candidate, dict):
                    pipeline = candidate
            except (OSError, ValueError, json.JSONDecodeError):
                pipeline = None

    if pipeline and (
        metadata.get("generation_timing_basis") != "active_stages"
        or not params.get("model_type")
        or not params.get("resolution")
    ):
        from services.director_pipeline import enrich_output_metadata_with_pipeline_timing
        metadata = enrich_output_metadata_with_pipeline_timing(metadata, pipeline)

    from services.video_extra_info import build_saved_clip_info, build_saved_video_context
    context = build_saved_video_context(metadata, pipeline)
    try:
        file_stat = os.stat(filepath)
        file_size_bytes = file_stat.st_size
        file_modified_at = file_stat.st_mtime
    except OSError:
        file_size_bytes = 0
        file_modified_at = None
    clip = build_saved_clip_info(
        name,
        metadata, pipeline=pipeline,
        file_size_bytes=file_size_bytes,
        file_modified_at=file_modified_at,
    )
    return meta_path, metadata, context, clip


@api.get("/api/v1/outputs/{name}/extra-info")
def get_video_extra_info(name: str, language: str = "en"):
    """Return cached publishing copy for one language, if it exists."""
    from services.video_extra_info import normalize_language

    try:
        code, label = normalize_language(language)
    except ValueError as error:
        raise HTTPException(status_code=400, detail=str(error)) from error
    _, metadata, context, clip = _saved_video_context_for_extra_info(name)
    stored = metadata.get("video_extra_info")
    cached = stored.get(code) if isinstance(stored, dict) else None
    # Ignore stale copy if a sidecar/pipeline prompt was edited after it was
    # generated. The next explicit Generate click refreshes and persists it.
    available = bool(
        isinstance(cached, dict)
        and cached.get("source_fingerprint") == context.get("source_fingerprint")
    )
    return {
        "available": available,
        "language": code,
        "language_label": label,
        "data": cached if available else None,
        "prompt_count": context.get("prompt_count", 0),
        "director_context": context.get("director_context", False),
        "clip": clip,
    }


@api.post("/api/v1/outputs/{name}/extra-info")
async def generate_output_extra_info(name: str, request: Request):
    """Generate and persist platform copy from saved prompts only."""
    from services import llm_service
    from services.video_extra_info import (
        generate_video_extra_info,
        normalize_language,
    )

    body = await request.json()
    try:
        code, _ = normalize_language(body.get("language", "en"))
    except ValueError as error:
        raise HTTPException(status_code=400, detail=str(error)) from error

    meta_path, metadata, context, _ = _saved_video_context_for_extra_info(name)
    stored = metadata.get("video_extra_info")
    cached = stored.get(code) if isinstance(stored, dict) else None
    if (
        not body.get("regenerate")
        and isinstance(cached, dict)
        and cached.get("source_fingerprint") == context.get("source_fingerprint")
    ):
        return {"cached": True, "data": cached}

    try:
        _ensure_llm_loaded()
        generated = generate_video_extra_info(context, code, llm_service.generate)
    except ValueError as error:
        raise HTTPException(status_code=422, detail=str(error)) from error
    except Exception as error:
        traceback.print_exc()
        raise HTTPException(status_code=500, detail=str(error)) from error

    generated["generated_at"] = time.time()
    latest = metadata
    try:
        # Re-read before the atomic update so another metadata writer cannot
        # be accidentally discarded while the LLM is working.
        with open(meta_path, "r", encoding="utf-8") as handle:
            candidate = json.load(handle)
        if isinstance(candidate, dict):
            latest = candidate
    except (OSError, ValueError, json.JSONDecodeError):
        pass
    saved = latest.get("video_extra_info")
    if not isinstance(saved, dict):
        saved = {}
        latest["video_extra_info"] = saved
    saved[code] = generated
    temp_path = f"{meta_path}.{uuid.uuid4().hex[:8]}.tmp"
    try:
        with open(temp_path, "w", encoding="utf-8") as handle:
            json.dump(latest, handle, indent=2, ensure_ascii=False, default=str)
        os.replace(temp_path, meta_path)
    except OSError as error:
        try:
            if os.path.isfile(temp_path):
                os.remove(temp_path)
        except OSError:
            pass
        raise HTTPException(status_code=500, detail="Could not save generated extra info") from error
    return {"cached": False, "data": generated}


@api.post("/api/v1/outputs/rejoin")
def rejoin_clips(body: dict):
    """Re-concatenate clips from a multi-clip group.

    Body: { group_id: str, audio_file?: str }
    Finds all clip files matching the group_id and re-concatenates them.
    """
    from services.mix_concat import concatenate_multi_clip_videos
    group_id = body.get("group_id")
    if not group_id:
        raise HTTPException(status_code=400, detail="group_id is required")

    out_dir = _workspace_dir()
    # Scan all sidecar files to find clips belonging to this group
    clips_by_index: dict[int, dict] = {}
    audio_path = None
    audio_start_sec = 0.0
    for fname in os.listdir(out_dir):
        if not fname.endswith(".meta.json"):
            continue
        meta_path = os.path.join(out_dir, fname)
        try:
            with open(meta_path, "r", encoding="utf-8") as f:
                meta = json.load(f)
            params = meta.get("params", {})
            mci = params.get("multi_clip_info")
            if not mci or mci.get("group_id") != group_id:
                continue
            media_name = fname.replace(".meta.json", "")
            # Try common extensions
            media_path = None
            for ext in (".mp4", ".mkv", ".webm"):
                candidate = os.path.join(out_dir, media_name + ext)
                if os.path.isfile(candidate):
                    media_path = candidate
                    break
            if not media_path:
                continue
            clips_by_index[mci["index"]] = {
                "path": media_path,
                "total": mci["total"],
            }
            # Get audio from first clip's params
            if mci["index"] == 0 and not audio_path:
                ag = mci.get("concat_audio_path") or params.get("audio_guide", "")
                if ag and os.path.isfile(ag):
                    audio_path = ag
                    try:
                        audio_start_sec = max(
                            0.0, float(mci.get("audio_start_sec", 0) or 0),
                        )
                    except (TypeError, ValueError):
                        audio_start_sec = 0.0
        except Exception:
            continue

    if not clips_by_index:
        raise HTTPException(status_code=404, detail=f"No clips found for group {group_id}")

    total = max(c["total"] for c in clips_by_index.values())
    # Build ordered list of clip paths
    clip_paths = []
    for i in range(total):
        if i in clips_by_index:
            clip_paths.append(clips_by_index[i]["path"])
        else:
            print(f"[Rejoin] Warning: missing clip index {i} for group {group_id}")

    if len(clip_paths) < 2:
        raise HTTPException(status_code=400, detail="Need at least 2 clips to rejoin")

    # Allow override audio from request body
    body_audio = body.get("audio_file")
    if body_audio and os.path.isfile(body_audio):
        audio_path = body_audio

    # Generate output path
    import time
    timestamp = time.strftime("%Y-%m-%d_%H%M%S")
    concat_name = f"{timestamp}_rejoin_multiclip.mp4"
    concat_path = os.path.join(out_dir, concat_name)

    success = concatenate_multi_clip_videos(
        clip_paths,
        concat_path,
        audio_path,
        audio_start_sec=audio_start_sec,
    )
    if not success or not os.path.isfile(concat_path):
        raise HTTPException(status_code=500, detail="Concatenation failed")

    return {"filename": concat_name, "clip_count": len(clip_paths)}


@api.get("/api/v1/outputs/group/{group_id}")
def get_group_clips(group_id: str):
    """Get all clip files belonging to a multi-clip group."""
    out_dir = _workspace_dir()
    clips: list[dict] = []
    for fname in os.listdir(out_dir):
        if not fname.endswith(".meta.json"):
            continue
        meta_path = os.path.join(out_dir, fname)
        try:
            with open(meta_path, "r", encoding="utf-8") as f:
                meta = json.load(f)
            params = meta.get("params", {})
            mci = params.get("multi_clip_info")
            if not mci or mci.get("group_id") != group_id:
                continue
            media_name = fname.replace(".meta.json", "")
            media_file = None
            for ext in (".mp4", ".mkv", ".webm"):
                candidate = media_name + ext
                if os.path.isfile(os.path.join(out_dir, candidate)):
                    media_file = candidate
                    break
            if media_file:
                clips.append({
                    "filename": media_file,
                    "index": mci["index"],
                    "total": mci["total"],
                    "prompt": params.get("prompt", ""),
                })
        except Exception:
            continue
    clips.sort(key=lambda c: c["index"])
    return {"group_id": group_id, "clips": clips}


